//! The TypeScript types the frontend uses for requests and replies, generated by ts-rs and
//! committed under `lib/bindings`, so the frontend builds without Rust. The test fails when a
//! type changes and they don't, and `UPDATE_BINDINGS=1 cargo test -p campaign-engine bindings`
//! rewrites them.
//!
//! Natively only: exporting writes files, which wasm32-unknown-unknown can't.

use crate::{ErrorBody, PlatformSummary, Request, Response};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use ts_rs::{Config, TS};

/// Where the bindings are committed.
const COMMITTED: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../lib/bindings");

/// A directory that's removed when dropped, so a failed assertion doesn't leave it behind.
struct TempDir(PathBuf);

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// Writes every type a request or a reply needs, each to its own file, into `dir`.
fn export(dir: &Path) {
    let cfg = Config::new().with_out_dir(dir);
    Request::export_all(&cfg).unwrap();
    Response::export_all(&cfg).unwrap();
    ErrorBody::export_all(&cfg).unwrap();
    PlatformSummary::export_all(&cfg).unwrap();
}

/// Each file in `dir`, by name, with its contents.
fn files(dir: &Path) -> BTreeMap<String, String> {
    std::fs::read_dir(dir)
        .unwrap()
        .map(|entry| {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            (name, std::fs::read_to_string(&path).unwrap())
        })
        .collect()
}

#[test]
fn bindings_are_committed() {
    if std::env::var_os("UPDATE_BINDINGS").is_some() {
        let _ = std::fs::remove_dir_all(COMMITTED);
        export(Path::new(COMMITTED));
        return;
    }
    let dir = TempDir(std::env::temp_dir().join(format!("campaign-ts-{}", std::process::id())));
    let _ = std::fs::remove_dir_all(&dir.0);
    export(&dir.0);
    let generated = files(&dir.0);
    for name in [
        "Request.ts",
        "Response.ts",
        "ErrorBody.ts",
        "PlatformSummary.ts",
        "Method.ts",
        "MeanVariance.ts",
        "RollingWindow.ts",
        "CutupError.ts",
    ] {
        assert!(generated.contains_key(name), "{name} wasn't exported");
    }
    assert_eq!(
        generated,
        files(Path::new(COMMITTED)),
        "lib/bindings is stale: run `UPDATE_BINDINGS=1 cargo test -p campaign-engine bindings`"
    );
}
